{
 "app_name": "splitwise",
 "api_name": "record_payment",
 "path": "/payments",
 "method": "POST",
 "description": "Record a new payment for an expense. This only records payment on splitwise and does not move real money.",
 "parameters": [
  {
   "name": "payer_email",
   "type": "string",
   "required": true,
   "description": "Email of the user who made the payment.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "receiver_email",
   "type": "string",
   "required": true,
   "description": "Email of the user who received the payment.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "amount",
   "type": "number",
   "required": true,
   "description": "The amount of the payment.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from splitwise app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "group_id",
   "type": "integer",
   "required": false,
   "description": "The ID of the group to record the payment in.",
   "default": null,
   "constraints": []
  },
  {
   "name": "description",
   "type": "string",
   "required": false,
   "description": "A short note or description of the payment.",
   "default": null,
   "constraints": []
  },
  {
   "name": "receipt_file_path",
   "type": "string",
   "required": false,
   "description": "Receipt file path to attach as an evidence of this payment made (e.g., snapshot of bank transfer, venmo, etc.)",
   "default": null,
   "constraints": []
  },
  {
   "name": "file_system_access_token",
   "type": "string",
   "required": false,
   "description": "Access token obtained from file_system app login. Only needed for attaching receipt file.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string",
   "payment_id": 1
  },
  "failure": {
   "message": "string"
  }
 }
}

{
 "app_name": "splitwise",
 "api_name": "show_activity",
 "path": "/account/activity",
 "method": "GET",
 "description": "Show a history of your expenses and payments combined.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from splitwise app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "show_expenses",
   "type": "boolean",
   "required": false,
   "description": "Whether to show expenses in the history.",
   "default": true,
   "constraints": []
  },
  {
   "name": "show_payments",
   "type": "boolean",
   "required": false,
   "description": "Whether to show payments in the history.",
   "default": true,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1.0, <= 20.0"
   ]
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the expenses/payments by prefixed with +/- to reflect ascending/descending. Valid attributes: created_at.",
   "default": "-created_at",
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "record_type": "expense",
    "amount": 0.0,
    "paid_by": {
     "name": "string",
     "email": "user@example.com"
    },
    "owed_by": [
     {
      "name": "string",
      "email": "user@example.com",
      "amount": 0.0
     }
    ],
    "description": "string",
    "group_id": 1,
    "group_name": "string",
    "created_at": "2019-01-01T00:00:00"
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}

{
 "app_name": "splitwise",
